	sections = {
		{
			title = "Summary",
			text = [=[Red Cloud Mesa is the high tableland in the south of {link:mulgore}Mulgore{/link}, where young {link:tauren}tauren{/link} take their first steps as hunters. Plainstriders and mountain cougars roam its grass, and the elders say that its people pride themselves on keen hunting above all else. A well lies south-east of the camp, where the Greatmother of the Hawkwinds draws water. In the hills to the south the seer {link:seer-graytongue}Graytongue{/link} keeps his abode, and above the far south-eastern slopes stands a shrine to An'she and Mu'sha. East of the mesa opens {link:brambleblade-ravine}Brambleblade Ravine{/link}, from which the {link:bristleback-quilboar}Bristleback quilboar{/link} come by night to ambush hunters and steal from the camp.]=],
