	sections = {
		{
			title = "Summary",
			text = [=[Camp Narache is the camp of {link:chief-hawkwind}Chief Hawkwind{/link} on {link:red-cloud-mesa}Red Cloud Mesa{/link}. It is a place of tents, totems and cookfires, and it is where the young of the tribe begin the {link:rites-of-the-earthmother}Rites of the Earthmother{/link}. The chief teaches that every member of the tribe has a place in the balance of living things, and that the elders take note even of humble work. His son {link:grull-hawkwind}Grull{/link} tests the young hunters. The camp lives under threat, for the {link:bristleback-quilboar}Bristleback{/link} warchief has drawn up plans to lay siege to it. Those who prove themselves here follow the road north to {link:bloodhoof-village}Bloodhoof Village{/link}.]=],
		},
	},
})

