	sections = {
		{
			title = "Summary",
			text = [=[Bloodhoof Village lies in the heart of {link:mulgore}Mulgore{/link}, on the road between {link:red-cloud-mesa}Red Cloud Mesa{/link} and {link:thunder-bluff}Thunder Bluff{/link}. It is the village of {link:cairne-bloodhoof}Cairne{/link}'s own tribe, and his son {link:baine-bloodhoof}Baine{/link} leads it as chief. Around its great fire gather the tribe's teachers: the shaman {link:mull-thunderhorn}Mull Thunderhorn{/link}, who cleanses the poisoned wells, the spiritual leader {link:zarlman-two-moons}Zarlman Two-Moons{/link}, the warrior {link:ruul-eagletalon}Ruul Eagletalon{/link} and the hunters {link:harken-windtotem}Harken Windtotem{/link} and {link:skorn-whitecloud}Skorn Whitecloud{/link}. Its inn welcomes travellers. From Bloodhoof the young {link:tauren}tauren{/link} go out to the wells, the mine and the {link:gnolls}gnoll{/link} camps, and those who pass the Rite of Vision set out from here toward the city.]=],
		},
	},
})

