	sections = {
		{
			title = "Summary",
			text = [=[Three sacred wells water {link:mulgore}the plains of Mulgore{/link}, each named for a {link:tauren}tauren{/link} clan. The Winterhoof Water Well lies south-east of {link:bloodhoof-village}Bloodhoof Village{/link}, the Thunderhorn Water Well to its north, and the Wildmane Water Well north of {link:thunder-bluff}Thunder Bluff{/link}. The wells give life to the tauren and to the beasts they depend on. The goblins of the {link:venture-company}Venture Company{/link} and their servants have fouled all three. To cleanse them, the shaman {link:mull-thunderhorn}Mull Thunderhorn{/link} makes a totem for each from what the land itself offers, and a ritual must then be performed at the well, often under the eyes of goblin guards.]=],
		},
	},
})

