	sections = {
		{
			title = "Summary",
			text = [=[The Bael'dun Digsite lies in the west of {link:mulgore}Mulgore{/link}, north-west of {link:bloodhoof-village}Bloodhoof Village{/link}. {link:dwarves}Dwarves{/link} have raised a camp here and are digging into the earth, with diggers to break the ground and appraisers to judge what they find. They believe that secrets lie buried in Mulgore. Chief {link:baine-bloodhoof}Baine Bloodhoof{/link} does not doubt it. He holds only that tearing open and fouling the earth is the wrong way to learn its secrets, and he has asked that the dwarves' digging tools be taken and smashed.]=],
		},
