			areas = { 225 },
		},
	},
	regionKind = "place",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Red Rocks is the sacred burial ground of the {link:tauren}tauren{/link}, in the north-east of {link:mulgore}Mulgore{/link} beyond {link:thunder-bluff}Thunder Bluff{/link}. Only the most valiant are laid to rest here: the warriors who helped found and defend the city, and those who gave their lives for their tribes and chieftains. Ancestral spirits dwell among the stones, and it is here that young tauren who have drunk the Water of the Seers come to receive the blessing of their forebears. The old {link:lorekeeper-raintotem}Lorekeeper Raintotem{/link} watches over the graves. {link:bristleback-quilboar}Bristleback{/link} raiders have lately come onto the holy ground to ravage it.]=],
		},
	},
})

