	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[The Golden Plains spread east of {link:thunder-bluff}Thunder Bluff{/link}, a sea of tall grass between the city and the eastern cliffs. Flatland cougars hunt here, and the old strider {link:mazzranache}Mazzranache{/link} is said to roam the same country. Now and then a great white wolf called {link:ghost-howl}Ghost Howl{/link} crosses these plains, its hide still scarred from battle with demons. The goblins of the {link:venture-company}Venture Company{/link} cut their roads across the grass between their mine and the wells. In these days one of their shredders has been seen on the plains, a machine the {link:tauren}tauren{/link} will not suffer to fell a single tree of {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

