			hint = "Learn the chief's judgment on the gnolls of Mulgore.",
			unlock = {
				{ type = "quest", id = 745 },
			},
			text = [=[The {link:palemane-gnolls}Palemane gnolls{/link} came into {link:mulgore}Mulgore{/link} and slew its wildlife without restraint. The {link:tauren}tauren{/link} tried again and again to reach them with words. Baine at last concluded that words were no longer the answer. He wished to show the young how terrible even a small threat can become if it is left unchecked.]=],
