			hint = "Deal with the centaur who have crossed into Mulgore.",
			unlock = {
				{ type = "quest", id = 99080 },
			},
			text = [=[When the report of the slain {link:longwalkers}Longwalker{/link} Malah reached him, Baine read it in silence. Then he declared that the {link:tauren}tauren{/link} would not yield a single blade of grass to the {link:centaurs}centaur{/link}. He sent warriors to strike the Galak camp before its riders could reach his village, and asked that the head of their leader be brought back as a warning to others.]=],
