Add({
	kind = "figure",
	id = "muln-earthfury",
	title = "Muln Earthfury",
	aliases = { "Muln" },
	subtitle = "Elder of the Earthen Ring",
	tier = "A",
	region = "mulgore",
	npc = { 259118, 256620 },
	allegiance = "Earthen Ring · Tauren",
	found = "Camp Gev'rek, on Skywatcher Plateau",
	unlock = {
		{ type = "interact" },
	},
	hint = "Seek the elder shaman who welcomes the Skyborne to Mulgore.",
	sections = {
		{
			title = "Summary",
			text = [=[Muln Earthfury is a {link:tauren}tauren{/link} shaman and a leader of the {link:earthen-ring}Earthen Ring{/link}, the council that keeps the balance of the {link:elements}Elements{/link}. In these days his duty to the spirits took him beyond the world itself, to {link:skywall}Skywall{/link}, the realm of the air. There he answered the call of the {link:windshapers}Windshapers{/link}, and when he returned he brought them with him.]=],
		},
		{
			title = "Significance",
			text = [=[Muln is the bridge between the {link:skyborne}Skyborne{/link} and {link:azeroth}Azeroth{/link}. Through him the {link:windshapers}Windshapers{/link} found the {link:earthen-ring}Earthen Ring{/link}, and through the Ring they found the {link:horde}Horde{/link}. The elves who come down to {link:mulgore}Mulgore{/link} are his guests, and they know the world at first through his camp and his counsel.]=],
		},
		{
			title = "Deeds",
			text = [=[• He answered the plea of the {link:windshapers}Windshaper{/link} leader {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}, whose home was failing.
• He went with shamans of the {link:earthen-ring}Earthen Ring{/link} to {link:zephras-isle}Zephras Isle{/link} to aid the {link:skyborne}Skyborne{/link}.
• He faced one of the great lords of the wind and told it that the Ring had no quarrel with it.
• He warned the Windshapers of the elemental lords, and of good reason to fear {link:al-akir}Al'Akir{/link}.
• He opened a road of skycutter ships between Zephras Isle and {link:mulgore}Mulgore{/link}.
• He keeps the camp on {link:camp-gev-rek}Skywatcher Plateau{/link} where the newcomers arrive.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written of Muln's life before these days. The chronicles of this age do not record when he rose to lead the Ring, or how {link:ayessa-dawnsinger}Ayessa{/link} first reached him across the planes.]=],
		},
	},
	chapters = {
		{
			key = "help-from-below",
			title = "Help from Below",
			hint = [=[Stand with the Windshapers in their darkest hour on Zephras Isle.]=],
			unlock = {
				{ type = "quest", id = 92646 },
			},
			text = [=[The {link:windshapers}Windshapers{/link} had sent for help, and it was slow to come. When Muln and the shamans of the {link:earthen-ring}Earthen Ring{/link} arrived at last, the battle against the cult of the {link:high-priestess-lorthuna}High Priestess Lorthuna{/link} was already raging. He asked {link:ayessa-dawnsinger}Ayessa{/link}'s pardon for coming late. When the Lord of the East Wind came upon them, Muln spoke for the Ring: they had no quarrel with him, and asked only to be left in peace. When the battle was over, he returned at once to {link:azeroth}Azeroth{/link}.]=],
		},
		{
			key = "the-warning",
			title = "The Warning",
			hint = [=[Learn what the Earthen Ring told the Windshapers of the Windlord.]=],
			unlock = {
				{ type = "quest", id = 93836 },
			},
			text = [=[Muln told {link:ayessa-dawnsinger}Ayessa{/link} much of the elemental lords. What he told her left her afraid. The wards that had hidden {link:zephras-isle}Zephras Isle{/link} were gone, and nothing stood between the island and {link:al-akir}Al'Akir{/link} in his own domain. The High Elder of the {link:skyborne}Skyborne{/link} took a longer view: to an elemental lord, years or even decades might pass before he turned his eyes their way.]=],
		},
		{
			key = "the-skycutter-road",
			title = "The Skycutter Road",
			hint = "Take ship from Zephras Isle to the land of the Earthen Ring.",
			unlock = {
				{ type = "quest", id = 93090 },
			},
			text = [=[Muln worked hard to make the crossing safe. Test voyages sailed between the island and {link:mulgore}Mulgore{/link}, where the {link:earthen-ring}Earthen Ring{/link} make their home, until the skycutters ran steadily and the first {link:skyborne}Skyborne{/link} were already waiting on the other side.]=],
		},
	},
	mentions = {
		{
			text = [=[The {link:earthen-ring}Earthen Ring{/link}, his camp in {link:mulgore}Mulgore{/link}]=],
			unlock = {
				{ type = "quest", id = 95349 },
			},
		},
		{
			text = "Child of Nature",
			unlock = {
				{ type = "quest", id = 94911 },
			},
		},
		{
			text = "Exploring the {link:horde}Horde{/link}",
			unlock = {
				{ type = "quest", id = 93739 },
			},
		},
	},
	bonds = {
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "receives the Windshapers at his camp" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "High Chieftain of his people" },
		{ id = "thrall", name = "Thrall", note = "warchief of the Horde and a shaman" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "of the Cenarion Circle, which welcomes his guests" },
