Add({
	kind = "topic",
	id = "bristleback-quilboar",
	title = "Bristleback Quilboar",
	aliases = { "Bristleback quilboar", "Bristlebacks", "Bristleback" },
	category = "group",
	region = "mulgore",
	unlock = {
		{ type = "target" },
		{ type = "read" },
	},
	npc = { 2952, 2953, 2954, 3232 },
	sections = {
		{
			title = "Summary",
			text = [=[The Bristlebacks are the tribe of {link:quilboar}quilboar{/link} who live in {link:mulgore}Mulgore{/link}. They were there before the {link:tauren}tauren{/link} settled the plains, and they have been at war with them ever since. From their thorny village in {link:brambleblade-ravine}Brambleblade Ravine{/link} they strike at {link:red-cloud-mesa}Red Cloud Mesa{/link}, and their raiders reach as far north as the burial ground of {link:red-rocks}Red Rocks{/link}.]=],
		},
		{
			title = "Ways of War",
			text = [=[The Bristlebacks fight from ambush. Their warriors lie in wait for {link:tauren}tauren{/link} hunting parties and steal into {link:camp-narache}Camp Narache{/link} by dark. Their shamans fight beside them. They train battleboars, the great boars of the ravine, to be malicious, and send them onto the tauren hunting grounds. Their warchief drew up plans for a long siege of Camp Narache.]=],
		},
		{
			title = "In These Days",
			text = [=[The young {link:tauren}tauren{/link} of {link:camp-narache}Narache{/link} prove their strength against the Bristlebacks, and the belts of fallen raiders are the first trophies of the Rite of Strength. Bristleback interlopers have lately been ravaging the graves at {link:red-rocks}Red Rocks{/link}. Their chief, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, rules the ravine.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "palemane-gnolls",
	title = "Palemane Gnolls",
	aliases = { "Palemane gnolls", "Palemane" },
	category = "group",
	region = "mulgore",
	unlock = {
		{ type = "target" },
		{ type = "read" },
	},
	npc = { 2949, 2950, 2951 },
	sections = {
		{
			title = "Summary",
			text = [=[The Palemane are a tribe of {link:gnolls}gnolls{/link} who have settled in {link:mulgore}Mulgore{/link}. They lair in the cave of {link:palemane-rock}Palemane Rock{/link} in the western hills and keep camps south of {link:bloodhoof-village}Bloodhoof Village{/link}. They are poachers, skinners and tanners, and they slay the wildlife of the plains without restraint.]=],
		},
		{
			title = "The Tauren and the Palemane",
			text = [=[The {link:tauren}tauren{/link} tried to share the land with them. Again and again they sought to speak with the gnolls, and each time they were met with disrespect. Chief {link:baine-bloodhoof}Baine Bloodhoof{/link} at last judged that words were no longer the answer. Even so, the High Chieftain made one more attempt in these days, and sent his {link:longwalkers}Longwalker{/link} {link:perith-stormhoof}Perith Stormhoof{/link} to them. The gnolls seized him and held him in their cave.]=],
		},
		{
			title = "Their Haunts",
			text = [=[The tanners and skinners of the tribe work the hides of their kills around {link:palemane-rock}Palemane Rock{/link}, while poachers range across the western hills. Among the camps south of Bloodhoof prowls a {link:gnolls}gnoll{/link} called Snagglespear.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "windfury-harpies",
	title = "Windfury Harpies",
	aliases = { "Windfury harpies", "Windfury" },
	category = "group",
	region = "mulgore",
	unlock = {
		{ type = "target" },
		{ type = "read" },
	},
	npc = { 2962, 2963, 2964, 2965 },
	sections = {
		{
			title = "Summary",
			text = [=[The Windfury are the {link:harpies}harpies{/link} of {link:mulgore}Mulgore{/link}. Their flocks nest on the mountain edges of the south-east, away from the roads, and above all on {link:windfury-ridge}Windfury Ridge{/link} in the far north. The {link:tauren}tauren{/link} count them among the natural enemies of their land.]=],
		},
		{
			title = "Nature",
			text = [=[The Windfury flocks are ruled by matriarchs, and their witches and sorceresses command the wind. They prey on whatever walks below their roosts. Their plumage is prized by the {link:tauren}tauren{/link}: the azure and bronze feathers of the northern flocks are used for the headdresses that young tauren wear when they stand before the High Chieftain.]=],
		},
		{
			title = "In These Days",
			text = [=[{link:ruul-eagletalon}Ruul Eagletalon{/link} of Bloodhoof sends young warriors against the flocks of the south-east as a test of strength. The northern flocks are stronger, and their sorceresses and matriarchs rule the heights of {link:windfury-ridge}Windfury Ridge{/link}. A {link:harpies}harpy{/link} called Sister Hatelash has been seen among the north-western crags, not far from the plateau where the {link:earthen-ring}Earthen Ring{/link} has made its camp.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "longwalkers",
	title = "Longwalkers",
	aliases = { "Longwalker" },
	category = "group",
	region = "mulgore",
	unlock = {
		{ type = "quest", id = 98430 },
		{ type = "quest", id = 99079 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Longwalkers are the most trusted scouts of the {link:tauren}tauren{/link}. They answer to the High Chieftain {link:cairne-bloodhoof}Cairne Bloodhoof{/link} alone, and they carry his most secret errands. A Longwalker can be known by a headband and a feathered staff. Even the chief of {link:bloodhoof-village}Bloodhoof Village{/link}, Cairne's own son, may only ask for their help.]=],
		},
		{
			title = "Their Ways",
			text = [=[Secrecy is the first law of the Longwalkers. They travel alone, they do not speak of their missions, and when one is saved from danger he goes on alone rather than tell anyone where he is going. When a Longwalker does not return from a watch, the braves of the nearest village must go and learn why.]=],
		},
		{
			title = "In These Days",
			text = [=[Two Longwalkers have been in danger in {link:mulgore}Mulgore{/link}. {link:perith-stormhoof}Perith Stormhoof{/link}, whom {link:cairne-bloodhoof}Cairne{/link} calls his most trusted scout, was sent to treat with the {link:palemane-gnolls}Palemane gnolls{/link} and was taken prisoner. Malah Longwind was sent to watch the eastern border and was slain by Galak {link:centaurs}centaur{/link}, her report still in her hand.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "rites-of-the-earthmother",
	title = "Rites of the Earthmother",
	aliases = { "Rites of the Earth Mother" },
	category = "concept",
	region = "mulgore",
	unlock = {
		{ type = "quest", id = 755 },
		{ type = "quest", id = 763 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Rites of the Earthmother are the trials by which a young {link:tauren}tauren{/link} earns the respect of the elders of {link:thunder-bluff}Thunder Bluff{/link}. There are three: the Rite of Strength, the Rite of Vision and the Rite of Wisdom. Together they lead from the first camp on {link:red-cloud-mesa}Red Cloud Mesa{/link} to the lodge of the High Chieftain.]=],
		},
		{
			title = "The Three Rites",
			text = [=[• {b}The Rite of Strength.{/b} {link:chief-hawkwind}Chief Hawkwind{/link} and the seer {link:seer-graytongue}Graytongue{/link} send the young against the {link:bristleback-quilboar}Bristleback{/link} raiders of {link:brambleblade-ravine}Brambleblade Ravine{/link}, to bring back their belts as proof of valor.
• {b}The Rite of Vision.{/b} At {link:bloodhoof-village}Bloodhoof Village{/link}, {link:zarlman-two-moons}Zarlman Two-Moons{/link} brews the Water of the Seers from well stones and ambercorn. Drunk before the tribal fire, it calls up a vision of the plains that leads the drinker to the seer {link:seer-wiserunner}Wiserunner{/link}.
• {b}The Rite of Wisdom.{/b} At {link:red-rocks}Red Rocks{/link}, the ancestral spirits give their blessing to those who have drunk the Water of the Seers.]=],
		},
		{
			title = "The Journey's End",
			text = [=[Those who pass the rites are honored in {link:thunder-bluff}Thunder Bluff{/link}. Their last step is to climb to the highest mesa and stand before {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Even then the test is not over. To keep the place they have won, the High Chieftain sends them to track and slay Arra'chea, a mighty kodo of the plains.]=],
		},
	},
})
